window.RP_SESSION={"id":"S-f1c093a1d5cf","messages":[{"id":"RP-II-0102305","time":"2026-05-18T18:48:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"···.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102306","time":"2026-05-18T18:50:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이런 저런 일이 많았다. 고난과 고난. 그 속에서도 어느정도 안정되고 나니. 자연스럽게 베스퍼가 책을 잡는 것은 어쩌면 자연스러운 수순이었다.\n\n훈련장 근처, 나무 아래 그늘에서 책을 한가로이 넘기며 읽고 있지만.\n\n······ 책 내용이 쉽지 않다.\n\n마법에 관련된 기본적 활용도서, 라고는 적혀있으나···. 매우 두꺼운 책. 이런 건 또 어디서 가져왔나 싶을 정도의 두께다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102307","time":"2026-05-18T18:51:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그것이 마냥 재미있다는 듯 흥얼거리며, 배 위에 올려놓고 한 페이지, 한 페이지, 찬찬히 넘기기 시작했다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102308","time":"2026-05-18T18:52:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명+2","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102309","time":"2026-05-18T18:52:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 5 + 2 = 7\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0102310","time":"2026-05-18T18:53:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아얏, 탕. 가벼운 소리와 동시에 뭉특한 나뭇가지가 베스퍼의 머리를 가격했다.\n\n“ 씁, 아야···. ”\n\n박박, 복슬거리는 머리를 이리저리 문질러대기 시작했다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102311","time":"2026-05-18T18:54:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명+2","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102312","time":"2026-05-18T18:54:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 3 + 2 = 5\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0102313","time":"2026-05-18T18:54:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 으하학, 아야, 아, 및, 미친! ”\n\n정확히 문지르는 그 손 위로 무언가가 떨어졌다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102314","time":"2026-05-18T18:56:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······. 뭔가 뭉특하고. 거슬거슬한.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102315","time":"2026-05-18T18:56:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"송 충 이","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102316","time":"2026-05-18T18:56:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102317","time":"2026-05-18T18:56:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"🐛","characters":[]},{"id":"RP-II-0102318","time":"2026-05-18T18:57:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 늑, 늑ㅇ,ㄱ,  ”\n\n느아아아! 큰 소리가 울려퍼졌다. 벌레는 무섭지 않으나 유독 송충이를 싫어하는 이유는.\n\n오묘한 질감의 털과···. 미친듯한 가려움을 유발하는 그것의 속성 때문이라!","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102319","time":"2026-05-18T18:57:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102320","time":"2026-05-18T18:57:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 9 = 9\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0102321","time":"2026-05-18T18:58:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"탈탈탈탈탈탈탈탈\n\n격하게 손을 마구 털어댔다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102322","time":"2026-05-18T18:58:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102323","time":"2026-05-18T18:58:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 12 = 12\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0102324","time":"2026-05-18T18:58:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"오호라! 운이 좋게도 간지러움증은 없다.\n\n제 때 잘 빠르게 털어냈나봐. 베스퍼는 기분 좋은 듯 옅은 소리를 내고 다시금 천천히 몸을 뉘였다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102325","time":"2026-05-18T18:59:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102326","time":"2026-05-18T18:59:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 4 = 4\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0102327","time":"2026-05-18T18:59:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"킁, 흠······. 졸······.\n\n어.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102328","time":"2026-05-18T18:59:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"왜······ 얼굴이, 전부 복슬복슬하고 가렵지?","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102329","time":"2026-05-18T19:00:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"응?","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102330","time":"2026-05-18T19:00:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······ 응???!","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102331","time":"2026-05-18T19:00:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!d20","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102332","time":"2026-05-18T19:00:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결과 : [6]\n합계 : [6]","characters":[]},{"id":"RP-II-0102333","time":"2026-05-18T19:00:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"6마리의 송충이가, 베스퍼 머리 위에 안착했다.\n\n“ 으아아아악! ”\n\n······ 산들산들 불어오는 바람. 얼굴 위에는 아무것도 얹혀져 있지 않았다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102334","time":"2026-05-18T19:01:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"생각해보니, 나 가면을 썼는데 얼굴에 어떻게 느껴져.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102335","time":"2026-05-18T19:01:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"개꿈이다.","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102336","time":"2026-05-18T19:01:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"ㅋㅋ","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102337","time":"2026-05-18T19:01:00+09:00","room":"RP II","name":"베스퍼","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-051c3e67e69c"]},{"id":"RP-II-0102338","time":"2026-05-18T19:01:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
